class Solution {
public:
    string maximumXor(string s, string t) {
        int zeros = count(t.begin(), t.end(), '0');
        int ones = (int)t.size() - zeros;
        string ans;
        ans.reserve(s.size());
        for (char c : s) {
            if (c == '0') {
                if (ones) { ans += '1'; --ones; }
                else { ans += '0'; --zeros; }
            } else {
                if (zeros) { ans += '1'; --zeros; }
                else { ans += '0'; --ones; }
            }
        }
        return ans;
    }
};
